Rewrite the following GNU C++ code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define PB push_back
#define MP make_pair
#define SZ size()
#define all(v) v.begin(), v.end()
#define REP(i, n) for(int i = 0; i < (int)n; i++)
#define ITR(i, j, n) for(int i = j; i < (int)n; i++)
#define mem(array, val) memset(array, val, sizeof(array))
#define READ(filename) freopen(filename, "r", stdin)
#define WRITE(filename) freopen(filename, "w", stdout)
#define Pii pair <int, int>
#define Fr first
#define Sc second
#define Long long long
#define si(a) scanf("%d", &a)
#define sl(a) scanf("%I64d", &a)
#define sd(a) scanf("%lf", &a)
#define sii(a, b) scanf("%d%d", &a, &b)
#define sll(a, b) scanf("%I64d%I64d", &a, &b)
#define sdd(a, b) scanf("%lf%lf", &a, &b)
#define Fast_IO ios_base::sync_with_stdio(0);cin.tie(0)
#define debug(x) cout << #x << ": " << x << endl

#define MAX 1000005
const Long mod = 1000000007;
int P, K, cycle[MAX], mark[MAX];
vector <int> vec;

int main() {
   Long ans = 1;
   sii(P, K);
   if(!K) {
      ITR(i, 1, P) ans = (ans*P) % mod;
      cout << ans << endl;
      return 0;
   }

   ITR(i, 1, P) if(!mark[i]) {
      Long nd = i, len = 0;
      while(!mark[nd]) {
         mark[nd] = 1;
         nd = (K * nd) % P;
         len++;
      }
      cycle[len]++;
      vec.PB(len);
   }
   REP(i, vec.SZ) {
      Long tmp = (vec[i] * cycle[vec[i]]) % mod;
      ans = (ans * (tmp + 1)) % mod;
   }
   if(K == 1) ans = (ans * P) % mod;
   printf("%I64d\n", ans);

   return 0;
}

</original_code>
